// Everything here must be DETERMINISTIC: the island's output is byte-diffed
// against real Node, so nothing may depend on the clock, the pid, the cwd or
// the environment.
const { EventEmitter } = require("events");
const util = require("util");
const querystring = require("querystring");
const { Buffer } = require("buffer");
const { StringDecoder } = require("string_decoder");
const punycode = require("punycode");
const path = require("path");
const assert = require("assert");

function events() {
  const emitter = new EventEmitter();
  const seen = [];
  emitter.on("tick", (n) => seen.push("on:" + n));
  emitter.once("tick", (n) => seen.push("once:" + n));
  emitter.prependListener("tick", (n) => seen.push("pre:" + n));
  emitter.emit("tick", 1);
  emitter.emit("tick", 2);
  seen.push("names:" + emitter.eventNames().join("+"));
  seen.push("count:" + emitter.listenerCount("tick"));
  return seen.join("|");
}

function inspect() {
  return [
    util.inspect({ a: 1, b: [2, 3], c: "x" }),
    util.inspect(new Map([["k", 1]])),
    util.inspect([1, [2, [3, [4]]]], { depth: 1 }),
    util.format("%s/%d/%j", "s", 7.5, { j: true }),
    // %o is deliberately absent: the shared shim's %o does not carry
    // Node's showHidden output ([length] on an array), and that gap is
    // the same on both islands — it is not what this fixture pins.
    util.format("%i|%%|%s", "42abc", "z"),
    String(util.types.isDate(new Date(0))) + String(util.types.isRegExp(/x/)),
    String(util.isDeepStrictEqual({ a: [1] }, { a: [1] })),
  ].join("|");
}

function query() {
  const parsed = querystring.parse("a=1&b=two&b=three&c=%C3%A9&d");
  return [
    JSON.stringify(parsed),
    querystring.stringify({ a: 1, b: ["x", "y"], c: "é" }),
    querystring.escape("a b+c/d"),
    querystring.unescape("a%20b%2Bc"),
  ].join("|");
}

function buffers() {
  const b = Buffer.from("héllo wörld", "utf8");
  const decoder = new StringDecoder("utf8");
  const head = decoder.write(b.subarray(0, 2));
  const tail = decoder.write(b.subarray(2)) + decoder.end();
  return [
    b.length,
    b.toString("hex"),
    b.toString("base64"),
    Buffer.concat([Buffer.from("ab"), Buffer.from("cd")]).toString(),
    Buffer.from("QUJD", "base64").toString("utf8"),
    b.slice(0, 6).toString("utf8"),
    String(Buffer.compare(Buffer.from("a"), Buffer.from("b"))),
    b.readUInt8(0) + ":" + b.indexOf("wörld"),
    head + "/" + tail,
  ].join("|");
}

function paths() {
  return [
    path.join("/a", "b", "../c", "./d"),
    path.resolve("/a/b", "../c"),
    path.normalize("/a//b/../c/"),
    path.dirname("/a/b/c.txt"),
    path.basename("/a/b/c.txt", ".txt"),
    path.extname("/a/b/c.tar.gz"),
    String(path.isAbsolute("a/b")) + String(path.isAbsolute("/a")),
    path.relative("/a/b/c", "/a/d"),
    JSON.stringify(path.parse("/a/b/c.txt")),
    path.format({ dir: "/a/b", name: "c", ext: ".txt" }),
    path.posix.join("x", "y") + path.win32.join("x", "y"),
    path.sep + path.delimiter,
  ].join("|");
}

function unicode() {
  return [
    punycode.toASCII("mañana.example"),
    punycode.toUnicode("xn--maana-pta.example"),
    punycode.encode("bücher"),
    punycode.decode("bcher-kva"),
  ].join("|");
}

function asserts() {
  const failures = [];
  assert.strictEqual(1, 1);
  assert.deepStrictEqual({ a: [1, 2] }, { a: [1, 2] });
  try {
    assert.strictEqual(1, 2);
  } catch (error) {
    failures.push(error.code + ":" + error.operator + ":" + error.generatedMessage);
  }
  try {
    assert.ok(false);
  } catch (error) {
    failures.push(error.code);
  }
  return failures.join("|");
}

// The randomness surface: node:crypto's shim reads globalThis.crypto once
// at shim-factory time, so none of this exists unless the realm's web
// prelude installed that global before the module bootstrap ran. Values
// are random; lengths, types and untouched bytes are not.
const nodeCrypto = require("crypto");

module.exports.probeRandom = function probeRandom() {
  const uuidV4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
  const view = new Uint8Array(4);
  // A view over part of a bigger buffer must be filled at its OWN byte
  // offset, leaving the bytes outside it zero.
  const framed = new Uint8Array(8);
  nodeCrypto.getRandomValues(framed.subarray(2, 6));
  return [
    "bytes:" + nodeCrypto.randomBytes(16).length + ":" + nodeCrypto.randomBytes(0).length,
    "uuid:" + uuidV4.test(nodeCrypto.randomUUID()),
    "uuid-global:" + uuidV4.test(globalThis.crypto.randomUUID()),
    "grv:" + (nodeCrypto.getRandomValues(view) === view) + ":" + view.length,
    "grv-global:" + (globalThis.crypto.getRandomValues(view) === view),
    "grv-offset:" + [framed[0], framed[1], framed[6], framed[7]].join(","),
    "int:" + (nodeCrypto.randomInt(3, 6) >= 3),
  ].join("|");
};

// events.on — the async iterator the export table has always announced.
// Every event here is emitted BEFORE the loop runs, so the iterator only
// ever drains its own buffer: no timer source is needed, which is what
// lets this run on the Rust island too.
module.exports.probeEventsOn = async function probeEventsOn() {
  const { on, once } = require("events");
  const out = ["types:" + typeof on + ":" + typeof once];

  const buffered = new EventEmitter();
  const ticks = on(buffered, "tick");
  buffered.emit("tick", 1);
  buffered.emit("tick", 2);
  buffered.emit("tick", 3);
  const seen = [];
  for await (const args of ticks) {
    seen.push(args[0]);
    if (args[0] === 2) break;
  }
  out.push("break:" + seen.join(","));

  const closing = new EventEmitter();
  const chunks = on(closing, "data", { close: ["end"] });
  closing.emit("data", "x");
  closing.emit("data", "y");
  closing.emit("end");
  const body = [];
  for await (const args of chunks) body.push(args[0]);
  out.push("close:" + body.join(""));

  const failing = new EventEmitter();
  const items = on(failing, "item");
  failing.emit("item", "kept");
  failing.emit("error", new Error("boom"));
  const before = [];
  let caught = "none";
  try {
    for await (const args of items) before.push(args[0]);
  } catch (error) {
    caught = error.message;
  }
  out.push("error:" + before.join(",") + ":" + caught);

  const settling = new EventEmitter();
  const pending = once(settling, "ready");
  settling.emit("ready", 7, 8);
  out.push("once:" + (await pending).join(","));
  return out.join("|");
};

module.exports.report = function report() {
  return [
    "events " + events(),
    "inspect " + inspect(),
    "query " + query(),
    "buffer " + buffers(),
    "path " + paths(),
    "punycode " + unicode(),
    "assert " + asserts(),
  ].join("\n");
};
